E, H = "نَعَمْ ✓", "لا ✗"


def mcq(q, d, y, sira=False):
    o = {"q": q, "d": d, "y": y}
    if sira:
        o["sira"] = True
    return o


def bank(cumleler, banka):
    """Boşluk doldurma: her boşluk için doğru + bankadan 3 kelime."""
    out = []
    for i, (q, d) in enumerate(cumleler):
        diger = [w for w in banka if w != d]
        y = [diger[(i * 3 + k) % len(diger)] for k in range(3)]
        out.append(mcq(q, d, y))
    return out


def esle(ciftler):
    """Eşleştirme: her sol öğe için sağ sütundaki bütün seçenekler."""
    sag = [b for _, b in ciftler]
    return [mcq(a + "  ←", b, [x for x in sag if x != b]) for a, b in ciftler]


def eh(cumleler):
    return [mcq(q, E if v else H, [H if v else E], True) for q, v in cumleler]


def bolum(ad, ar, puan, oge, tip="mcq", **k):
    b = {"ad": ad, "ar": ar, "puan": puan, "tip": tip, "oge": oge}
    b.update(k)
    return b


def kisim(baslik, ar, bolumler):
    return {"baslik": baslik, "ar": ar, "bolumler": bolumler}


