SORU = ["مِنْ أَيْنَ", "مَتى", "لِماذا", "كَيْفَ", "ما", "مَنْ", "كَمْ", "أَيْنَ", "في أَيِّ", "هَلْ"]


def soruSec(q, d, i):
    diger = [w for w in SORU if w != d]
    return mcq(q, d, [diger[(i * 2 + k) % len(diger)] for k in range(3)])


