def temizle(o):
    """not_ anahtarını not yap (Python’da not ayrılmış kelime)."""
    if isinstance(o, dict):
        return {("not" if k == "not_" else k): temizle(v) for k, v in o.items()}
    if isinstance(o, list):
        return [temizle(x) for x in o]
    return o


for s in (S1, S2, S3, S4, S5):
    s = temizle(s)
    top = sum(b["puan"] for k in s["kisimlar"] for b in k["bolumler"])
    with open(os.path.join(here, "veri%d.js" % s["id"]), "w", encoding="utf-8") as f:
        f.write("// Otomatik üretildi (veri.py). Toplam puan: %d\nvar SINAV = %s;\n" % (top, json.dumps(s, ensure_ascii=False, indent=1)))
    print(s["id"], top)
